Request: Describe a book: a graphic novel about a librarian on the moon. Output as JSON.

JSON Schema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "title",
    "authors",
    "isbn",
    "year",
    "genres"
  ],
  "properties": {
    "title": {
      "type": "string",
      "minLength": 1
    },
    "authors": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "minLength": 2
      }
    },
    "isbn": {
      "type": "string",
      "pattern": "^[0-9]{3}-[0-9]{10}$"
    },
    "year": {
      "type": "integer",
      "minimum": 1450,
      "maximum": 2100
    },
    "genres": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "enum": [
          "fiction",
          "non-fiction",
          "fantasy",
          "sci-fi",
          "mystery",
          "biography",
          "history",
          "science",
          "philosophy",
          "poetry"
        ]
      },
      "uniqueItems": true
    },
    "page_count": {
      "type": "integer",
      "minimum": 1
    }
  }
}

Return only the JSON object.

Request: Create a user profile based on this description: a podiatrist who collects vintage telephones

JSON Schema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "username",
    "email",
    "preferences",
    "joined"
  ],
  "properties": {
    "username": {
      "type": "string",
      "pattern": "^[a-z0-9_]{3,16}$"
    },
    "email": {
      "type": "string",
      "format": "email"
    },
    "preferences": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "theme",
        "notifications"
      ],
      "properties": {
        "theme": {
          "type": "string",
          "enum": [
            "light",
            "dark",
            "auto"
          ]
        },
        "notifications": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "email",
            "push"
          ],
          "properties": {
            "email": {
              "type": "boolean"
            },
            "push": {
              "type": "boolean"
            },
            "sms": {
              "type": "boolean"
            }
          }
        },
        "language": {
          "type": "string",
          "pattern": "^[a-z]{2}(-[A-Z]{2})?$"
        }
      }
    },
    "joined": {
      "type": "string",
      "format": "date"
    },
    "verified": {
      "type": "boolean"
    }
  }
}

Return only the JSON object.

